import click

@click.command()
@click.option("-n", "--count", default=1, show_default=True, help="Number of greetings.")
@click.option("--name", required=True, help="Who to greet.")
@click.option("--shout/--no-shout", default=False, help="Uppercase output.")
@click.option("-v", "--verbose", count=True, help="Repeat for more detail.")
@click.option("--tag", multiple=True, help="Tags to attach (repeatable).")
def greet(count, name, shout, verbose, tag):
    """Greet NAME a number of times."""
    msg = f"Hello, {name}!"
    for _ in range(count):
        click.echo(msg.upper() if shout else msg)
    if verbose:
        click.echo(f"verbosity={verbose} tags={tag}")

greet.main(["--name", "Ada", "-n", "2", "--shout", "-vv", "--tag", "x", "--tag", "y"],
           standalone_mode=False)
# HELLO, ADA!
# HELLO, ADA!
# verbosity=2 tags=('x', 'y')

import click

@click.command()
@click.argument("sources", nargs=-1, required=True)
@click.argument("dest")
@click.option("--dry-run", is_flag=True)
def copy(sources, dest, dry_run):
    """Copy SOURCES... to DEST."""
    for src in sources:
        click.echo(f"{'would copy' if dry_run else 'copy'} {src} -> {dest}")

copy.main(["a.txt", "b.txt", "backup/", "--dry-run"], standalone_mode=False)
# would copy a.txt -> backup/
# would copy b.txt -> backup/

copy.main(["--", "-odd-name.txt", "backup/"], standalone_mode=False)
# copy -odd-name.txt -> backup/

import enum
import pathlib
import click

class Fmt(enum.Enum):
    JSON = "json"
    CSV = "csv"

@click.command()
@click.option("--fmt", type=click.Choice(Fmt, case_sensitive=False), default="json")
@click.option("--level", type=click.IntRange(1, 10), default=5)
@click.option("--src", type=click.Path(exists=True, dir_okay=False, path_type=pathlib.Path))
@click.option("--out", type=click.File("w"), default="-")
def export(fmt, level, src, out):
    out.write(f"{fmt} level={level} src={src}\n")

export.main(["--fmt", "CSV", "--level", "3"], standalone_mode=False)
# Fmt.CSV level=3 src=None
try:
    export.main(["--level", "12"], standalone_mode=False)
except click.BadParameter as e:
    print(e.format_message())
# Invalid value for '--level': 12 is not in the range 1<=x<=10.

