import click

class Config:
    def __init__(self, env):
        self.env = env
        self.log = []

@click.group()
@click.option("--env", default="dev")
@click.pass_context
def cli(ctx, env):
    ctx.obj = Config(env)
    ctx.call_on_close(lambda: click.echo(f"closing ({len(ctx.obj.log)} actions)"))

@cli.command()
@click.argument("service")
@click.pass_obj
def deploy(cfg, service):
    cfg.log.append(service)
    click.echo(f"Deploying {service} to {cfg.env}")

cli.main(["--env", "prod", "deploy", "api"], standalone_mode=False)
# Deploying api to prod
# closing (1 actions)

import click
from click.testing import CliRunner

@click.command()
@click.option("--count", type=int, default=1)
@click.option("--name", prompt="Your name")
def hello(count, name):
    if name == "boom":
        raise RuntimeError("unexpected")
    for _ in range(count):
        click.echo(f"Hello {name}")

runner = CliRunner()
r = runner.invoke(hello, ["--count", "2"], input="Ada\n")
print(r.exit_code, repr(r.output))  # 0 'Your name: Ada\nHello Ada\nHello Ada\n'

r = runner.invoke(hello, ["--count", "x", "--name", "Ada"])
print(r.exit_code, "Invalid value" in r.output)   # 2 True

r = runner.invoke(hello, ["--name", "boom"])
print(r.exit_code, type(r.exception).__name__)    # 1 RuntimeError

import click
from click.testing import CliRunner

@click.command(context_settings={"auto_envvar_prefix": "APP"})
@click.option("--region", default="eu-west", show_envvar=True)
@click.option("--token", envvar="API_TOKEN", prompt=True, hide_input=True)
@click.confirmation_option(prompt="Deploy to production?")
def deploy(region, token):
    click.echo(f"deploying to {region} with token {token[:2]}***")

runner = CliRunner()
r = runner.invoke(deploy, input="s3cret\ny\n")
print(r.output)
# Token:
# Deploy to production? [y/N]: y
# deploying to eu-west with token s3***

r = runner.invoke(deploy, ["--yes"], env={"APP_REGION": "us-east", "API_TOKEN": "abc"})
print(r.output)   # deploying to us-east with token ab***

import re
from datetime import timedelta
import click

class Duration(click.ParamType):
    name = "duration"
    def convert(self, value, param, ctx):
        if isinstance(value, timedelta):
            return value
        m = re.fullmatch(r"(\d+)([smh])", value)
        if not m:
            self.fail(f"{value!r} is not like 30s, 5m or 2h", param, ctx)
        unit = {"s": "seconds", "m": "minutes", "h": "hours"}[m[2]]
        return timedelta(**{unit: int(m[1])})

def even_only(ctx, param, value):
    if value % 2:
        raise click.BadParameter("must be even")
    return value
@click.command()
@click.option("--timeout", type=Duration(), default="30s")
@click.option("--workers", type=int, default=2, callback=even_only)
def run(timeout, workers):
    click.echo(f"timeout={timeout.total_seconds():.0f}s workers={workers}")
run.main(["--timeout", "5m", "--workers", "4"], standalone_mode=False)  # timeout=300s workers=4

import click
from click.shell_completion import CompletionItem

ENVIRONMENTS = {"dev": "local cluster", "staging": "pre-prod", "prod": "live!"}

def complete_env(ctx, param, incomplete):
    return [CompletionItem(name, help=desc)
            for name, desc in ENVIRONMENTS.items() if name.startswith(incomplete)]

@click.command()
@click.argument("env", shell_complete=complete_env)
@click.option("--format", type=click.Choice(["json", "table"]))
def status(env, format):
    click.echo(f"{env}: ok")

items = complete_env(None, None, "st")
print([(i.value, i.help) for i in items])   # [('staging', 'pre-prod')]

