import importlib
import click

class LazyGroup(click.Group):
    def __init__(self, *args, lazy=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.lazy = lazy or {}                    # name -> "module:attr"

    def list_commands(self, ctx):
        return sorted([*super().list_commands(ctx), *self.lazy])

    def get_command(self, ctx, name):
        if name in self.lazy:
            module, attr = self.lazy[name].split(":")
            return getattr(importlib.import_module(module), attr)  # imported on demand
        matches = [c for c in self.list_commands(ctx) if c.startswith(name)]
        return super().get_command(ctx, matches[0]) if len(matches) == 1 else None
@click.group(cls=LazyGroup, lazy={"pretty": "json:tool"})   # demo target: any importable object
def cli():
    pass
@cli.command()
def status():
    click.echo("all good")
print(cli.list_commands(None))                   # ['pretty', 'status']
cli.main(["stat"], standalone_mode=False)          # all good  (unique prefix)

import click

class NotFound(click.ClickException):
    exit_code = 3

@click.command()
@click.argument("key")
def get(key):
    data = {"a": 1}
    if key not in data:
        raise NotFound(f"no such key: {key}")
    return data[key]

for args in (["a"], ["zzz"], []):
    try:
        get.main(args, prog_name="get")            # standalone mode
    except SystemExit as e:
        print("exit code", e.code)
# exit code 0
# Error: no such key: zzz                          (stderr)
# exit code 3
# Usage: get [OPTIONS] KEY ... Error: Missing argument 'KEY'.   (stderr)
# exit code 2

print(get.main(["a"], standalone_mode=False))     # 1  (return value, no exit)

import click
from click.core import ParameterSource

seen = []
def trace(ctx, param, value):
    seen.append(param.name)
    return value

@click.command()
@click.option("--a", default=1, callback=trace)
@click.option("--b", default=2, callback=trace, envvar="B_VAL")
@click.option("--c", default=3, callback=trace)
@click.pass_context
def cmd(ctx, a, b, c):
    for name in ("a", "b", "c"):
        click.echo(f"{name}={ctx.params[name]} from {ctx.get_parameter_source(name).name}")

cmd.main(["--c", "30", "--a", "10"], standalone_mode=False)
# a=10 from COMMANDLINE
# b=2 from DEFAULT
# c=30 from COMMANDLINE
print(seen)   # ['c', 'a', 'b']  (command-line order first, then the rest)
